Date: Sun, 22 Nov 2026 01:38:40 +0100
Subject: [PATCH] applets/notifications: don't show DND on the fullscreen
 window's screen

The Do Not Disturb icon flashed in the panel when entering or leaving
fullscreen, as the window didn't cover it yet or anymore. When only a
focused fullscreen window inhibits, panels on its screen now hide it.

BUG: 505169
---
 applets/notifications/global/Globals.qml     | 15 +++++++++-----
 applets/notifications/main.qml               | 16 ++++++++++++++-
 libnotificationmanager/fullscreentracker.cpp | 21 ++++++++++++++++++++
 libnotificationmanager/fullscreentracker_p.h |  6 ++++++
 libnotificationmanager/settings.cpp          |  7 +++++++
 libnotificationmanager/settings.h            | 12 +++++++++++
 6 files changed, 71 insertions(+), 6 deletions(-)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..0f56ec67cc 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -31,6 +31,8 @@ QtObject {
     signal timeChanged

     property bool inhibited: false
+    // Whether notifications are inhibited for a reason other than a focused fullscreen window
+    property bool inhibitedExceptFullscreen: false

     onInhibitedChanged: {
         // Explicitly update server state before potentially sending a inhibition summary,
@@ -273,7 +275,7 @@ QtObject {
     }

     function checkInhibition() {
-        globals.inhibited = Qt.binding(function() {
+        globals.inhibitedExceptFullscreen = Qt.binding(function() {
             var inhibited = false;

             if (!NotificationManager.Server.valid) {
@@ -289,16 +291,19 @@ QtObject {
                 inhibited |= true;
             }

-            if (notificationSettings.inhibitNotificationsWhenFullscreen) {
-                inhibited |= notificationSettings.fullscreenFocused;
-            }
-
             if (notificationSettings.inhibitNotificationsWhenScreensMirrored) {
                 inhibited |= notificationSettings.screensMirrored;
             }

             return inhibited;
         });
+        globals.inhibited = Qt.binding(function() {
+            if (globals.inhibitedExceptFullscreen) {
+                return true;
+            }
+
+            return NotificationManager.Server.valid && notificationSettings.inhibitNotificationsWhenFullscreen && notificationSettings.fullscreenFocused;
+        });
     }

     function revokeInhibitions() {
diff --git a/applets/notifications/main.qml b/applets/notifications/main.qml
index 8d98753eca..a3eea68488 100644
--- a/applets/notifications/main.qml
+++ b/applets/notifications/main.qml
@@ -33,10 +33,24 @@ PlasmoidItem {
         || Plasmoid.location === PlasmaCore.Types.BottomEdge
         || Plasmoid.location === PlasmaCore.Types.LeftEdge)

+    // A focused fullscreen window covers the panel on its own screen, but not those on other screens
+    readonly property bool showInhibited: {
+        if (Notifications.Globals.inhibitedExceptFullscreen) {
+            return true;
+        }
+        if (!Notifications.Globals.inhibited) {
+            return false;
+        }
+        const fullscreenScreen = notificationSettings.fullscreenFocusedScreenGeometry;
+        const screen = Plasmoid.containment.screenGeometry;
+        return fullscreenScreen.x !== screen.x || fullscreenScreen.y !== screen.y
+            || fullscreenScreen.width !== screen.width || fullscreenScreen.height !== screen.height;
+    }
+
     readonly property int effectiveStatus: historyModel.activeJobsCount > 0
                      || historyModel.unreadNotificationsCount > 0
                      || historyModel.dismissedResidentNotificationsCount > 0
-                     || Notifications.Globals.inhibited ? PlasmaCore.Types.ActiveStatus
+                     || showInhibited ? PlasmaCore.Types.ActiveStatus
                                           : PlasmaCore.Types.PassiveStatus
     onEffectiveStatusChanged: {
         if (effectiveStatus === PlasmaCore.Types.PassiveStatus) {
diff --git a/libnotificationmanager/fullscreentracker.cpp b/libnotificationmanager/fullscreentracker.cpp
index fd996ffbb9..cda87355c8 100644
--- a/libnotificationmanager/fullscreentracker.cpp
+++ b/libnotificationmanager/fullscreentracker.cpp
@@ -47,15 +47,36 @@ void FullscreenTracker::setFullscreenFocused(bool focused)
     }
 }

+QRect FullscreenTracker::fullscreenScreenGeometry() const
+{
+    return m_fullscreenScreenGeometry;
+}
+
+void FullscreenTracker::setFullscreenScreenGeometry(const QRect &geometry)
+{
+    if (m_fullscreenScreenGeometry != geometry) {
+        m_fullscreenScreenGeometry = geometry;
+        Q_EMIT fullscreenScreenGeometryChanged();
+    }
+}
+
 void FullscreenTracker::checkFullscreenFocused()
 {
     QModelIndex activeTaskIndex = m_tasks.activeTask();
     if (!activeTaskIndex.isValid()) {
         setFullscreenFocused(false);
+        setFullscreenScreenGeometry(QRect());
         return;
     }

     bool isFullscreen = activeTaskIndex.data(TaskManager::AbstractTasksModel::IsFullScreen).toBool();

+    // Set the geometry before and clear it after the focused state, so it's valid whenever that is true
+    if (isFullscreen) {
+        setFullscreenScreenGeometry(activeTaskIndex.data(TaskManager::AbstractTasksModel::ScreenGeometry).toRect());
+    }
     setFullscreenFocused(isFullscreen);
+    if (!isFullscreen) {
+        setFullscreenScreenGeometry(QRect());
+    }
 }
